// #155 AC-1/AC-2/AC-3 -- what the "Parsed fields" card shows, from the candidate API's real output for the
// complete and the sparse résumé (generated by the backend: scripts/gen-profile-fields-fixture.cjs): every
// field's value and status, a link to where each value was found, which values weren't found, and why a
// location is missing — the same for the same payload, so a refresh shows the same.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { parsedFieldRows } from "../../src/features/candidates/parsedFieldRows.ts";
import { ZH } from "../../src/data/i18n.ts";

const api = JSON.parse(readFileSync(new URL("./fixtures/profile-fields.json", import.meta.url), "utf8"));
const rows = (payload, lang = "en") => Object.fromEntries(parsedFieldRows(payload, lang).map((r) => [r.field, r]));

test("#155 AC-1/AC-2: the complete résumé shows all 12 fields as known, each with a link to its paragraph", () => {
  const all = parsedFieldRows(api.complete, "en");
  assert.equal(all.length, 12);
  for (const row of all) {
    assert.equal(row.status.label, "Known", row.field);
    assert.ok(row.values.length > 0, row.field);
    assert.ok(row.links.length > 0, row.field);
    assert.deepEqual(row.notes, [], row.field);
  }
  const r = rows(api.complete);
  assert.match(r.certifications.links[0].label, /^v2 · paragraph \d+$/);
  assert.equal(r.certifications.links[0].evidence.materialId, "m-1", "the link opens that résumé's source");
  assert.ok(r.certifications.links[0].evidence.segmentId);
  assert.match(rows(api.complete, "zh").certifications.links[0].label, /^v2 · 第 \d+ 段$/);
});

test("#155 AC-1: the sparse résumé shows the name, and every other field as not provided with no link or note", () => {
  const r = rows(api.sparse);
  assert.equal(r.name.status.label, "Known");
  for (const [field, row] of Object.entries(r)) {
    if (field === "name") continue;
    assert.equal(row.status.label, "Not provided", field);
    assert.deepEqual([row.values, row.links, row.notes], [[], [], []], field);
  }
});

test("#155 AC-2: a value that isn't in the source is named; an unreadable source says so instead of linking", () => {
  const partly = rows(api.partlyLocated).skills;
  assert.ok(partly.links.length > 0);
  assert.deepEqual(partly.notes, [{ text: "Not found in the source:", values: ["Kubernetes"] }]);
  for (const row of parsedFieldRows(api.sourceUnavailable, "en")) {
    assert.deepEqual(row.links, [], row.field);
    assert.deepEqual(row.notes, [{ text: "Source text unavailable" }], row.field);
  }
  for (const text of ["Not found in the source:", "Source text unavailable", "Not found in the source text", "Known", "Not provided", "Partly read"]) assert.ok(ZH[text], text);
});

test("#155 AC-3: the same payload always gives the same rows (a refresh shows the same)", () => {
  assert.deepEqual(parsedFieldRows(api.complete, "en"), parsedFieldRows(JSON.parse(JSON.stringify(api.complete)), "en"));
});
